<script setup lang="ts">
import { vMotionPanel } from '../../directives/siteMotion'
import { computed, ref } from 'vue'
import { ABILITY_KEYS, SKILL_ABILITY } from '../../lib/calc'
import { contentLabel, type SrdRef } from '../../lib/srd'
import { SLOT_PROGRESSIONS } from '../../../shared/character-progression'
import { newWorkshopFeature, newWorkshopResource, workshopProblems, WORKSHOP_STEPS, type WorkshopDraft, type WorkshopStep } from '../../lib/homebrew-workshop'
import WorkshopSchedule from './WorkshopSchedule.vue'
import { spellReferenceLabel } from '../../lib/spell-reference'
import RaceWorkshopEditor from './RaceWorkshopEditor.vue'
const props=defineProps<{draft:WorkshopDraft;step:WorkshopStep;classes:SrdRef[];spells:(SrdRef&{level?:number})[]}>()
const emit=defineEmits<{step:[value:WorkshopStep];save:[];publish:[]}>()
const spellQuery=ref('')
const spellResults=computed(()=>props.spells.filter(s=>`${s.name} ${s.sourcePack??''}`.toLowerCase().includes(spellQuery.value.toLowerCase())).slice(0,60))
const problems=computed(()=>workshopProblems(props.draft))
const stepIndex=computed(()=>WORKSHOP_STEPS.findIndex(s=>s.key===props.step))
const stepInfo=computed(()=>WORKSHOP_STEPS[stepIndex.value]!)
const words=(text:string)=>[...new Set(text.split(/\r?\n/).map(s=>s.trim()).filter(Boolean))]
function toggle<T>(array:T[],value:T){const i=array.indexOf(value);if(i>=0)array.splice(i,1);else array.push(value)}
const spellKey=(s:SrdRef)=>s.index
const unmatchedSpells=computed(()=>props.draft.magic.spellList.filter(key=>!props.spells.some(s=>s.index===key)))
</script>
<template><RaceWorkshopEditor v-if="draft.kind==='race'" :draft="draft" :step="step" :spells="spells" @step="emit('step',$event)" @save="emit('save')" @publish="emit('publish')" /><section v-else v-motion-panel="step" class="hw-editor hw-panel"><header class="hw-editor-header"><p class="hw-eyebrow">SECTION {{stepIndex+1}} OF {{WORKSHOP_STEPS.length}}</p><h2 tabindex="-1">{{stepInfo.name}}</h2><p class="hw-hint">{{stepInfo.hint}}</p></header>
  <div v-if="step==='identity'" class="hw-section-body"><div class="hw-intro"><h3>Give your creation a home.</h3><p>Name the class or subclass, describe its purpose, and choose the collection it belongs to.</p></div><div class="hw-form-grid"><label>Name<input v-model="draft.name" maxlength="200" placeholder="e.g. Revenant Shadow" /></label><label>Source / collection<input v-model="draft.source" maxlength="200" placeholder="e.g. My Book of Shadows" /></label></div><label v-if="draft.kind==='subclass'">Parent class<select v-model="draft.parentClass"><option value="">Choose a class…</option><option v-for="klass in classes" :key="klass.index" :value="klass.index">{{contentLabel(klass)}}</option></select></label><label>Introduction & flavour<textarea v-model="draft.description" rows="6" placeholder="What makes this class distinctive? What kind of adventurer does it create?" /></label><aside v-if="draft.imported" class="hw-callout"><strong>Imported content</strong><p>{{draft.imported.sources.join(' · ')||draft.source}}</p><p>The original rule fields remain attached to this draft. Saving to the original pack or another pack will be a separate, explicit choice.</p></aside></div>
  <div v-else-if="step==='foundation'" class="hw-section-body"><p v-if="draft.kind==='subclass'" class="hw-callout">A subclass inherits the parent class’s hit die and starting training. Record additional grants as features.</p><template v-else><div class="hw-form-grid"><label>Hit die<select v-model.number="draft.hitDie"><option v-for="die in [4,6,8,10,12]" :key="die" :value="die">d{{die}}</option></select></label><label>Skill choices at first level<input v-model.number="draft.skillCount" type="number" min="0" :max="draft.skillOptions.length" /></label><label>Expertise choices<input v-model.number="draft.expertiseCount" type="number" min="0" max="18" /></label></div><fieldset class="hw-check-group"><legend>Saving throw proficiencies</legend><label v-for="key in ABILITY_KEYS" :key="key"><input type="checkbox" :checked="draft.savingThrows.includes(key)" @change="toggle(draft.savingThrows,key)" />{{key.toUpperCase()}}</label></fieldset><fieldset class="hw-check-group hw-skills"><legend>Skills players may choose from</legend><label v-for="(_,key) in SKILL_ABILITY" :key="key"><input type="checkbox" :checked="draft.skillOptions.includes(String(key))" @change="toggle(draft.skillOptions,String(key))" />{{String(key).replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase())}}</label></fieldset><div class="hw-form-grid"><label>Armor proficiencies<textarea :value="draft.armor.join('\n')" rows="4" placeholder="Light armor&#10;Shields" @change="draft.armor=words(($event.target as HTMLTextAreaElement).value)" /></label><label>Weapon proficiencies<textarea :value="draft.weapons.join('\n')" rows="4" placeholder="All simple weapons&#10;All martial weapons" @change="draft.weapons=words(($event.target as HTMLTextAreaElement).value)" /></label><label>Tools & instruments<textarea :value="draft.tools.join('\n')" rows="4" placeholder="One entry per line" @change="draft.tools=words(($event.target as HTMLTextAreaElement).value)" /></label></div></template></div>
  <div v-else-if="step==='progression'" class="hw-section-body"><template v-if="draft.kind==='class'"><div class="hw-form-grid"><label>Subclass choice at level<input v-model.number="draft.subclassLevel" type="number" min="1" max="20" /></label><label>Subclass title<input v-model="draft.subclassTitle" placeholder="e.g. Shadow Knight" /></label></div><fieldset class="hw-check-group hw-level-grid"><legend>Ability increase / feat opportunities</legend><label v-for="level in 20" :key="level"><input type="checkbox" :checked="draft.asiLevels.includes(level)" @change="toggle(draft.asiLevels,level)" />{{level}}</label></fieldset><WorkshopSchedule v-model="draft.attacks" label="Attacks per Attack action" :maximum="10" /></template><p v-else class="hw-callout">The parent class supplies the main progression. Set each subclass feature’s gained level in Features & choices.</p></div>
  <div v-else-if="step==='magic'" class="hw-section-body"><label class="hw-check"><input v-model="draft.magic.enabled" type="checkbox" />{{draft.kind==='subclass'?'This subclass grants or changes spellcasting':'This class casts spells'}}</label><template v-if="draft.magic.enabled"><div class="hw-form-grid"><label>Casting ability<select v-model="draft.magic.ability"><option v-for="key in ABILITY_KEYS" :key="key" :value="key">{{key.toUpperCase()}}</option></select></label><label>Slot progression<select v-model="draft.magic.progression"><option v-for="(label,key) in SLOT_PROGRESSIONS" :key="key" :value="key">{{label}}</option></select></label><label>First casting class level<input v-model.number="draft.magic.startsAt" type="number" min="1" max="20" /></label><label>Spell learning<select v-model="draft.magic.learning"><option value="known">Fixed spells known</option><option value="prepared">Prepare from class list</option><option value="book">Spellbook</option></select></label></div><div class="hw-two-columns"><WorkshopSchedule v-model="draft.magic.cantrips" label="Cantrips known" /><WorkshopSchedule v-if="draft.magic.learning!=='prepared'" v-model="draft.magic.spells" :label="draft.magic.learning==='book'?'Starting spellbook total':'Spells known'" /><div v-if="draft.magic.learning!=='known'" class="hw-schedule"><h4>Prepared spell maximum</h4><label>Class level contribution<select v-model="draft.magic.preparedLevel"><option value="full">Full class level</option><option value="half">Half class level, rounded down</option><option value="none">No level contribution</option></select></label><label>Additional base amount<input v-model.number="draft.magic.preparedBase" type="number" min="0" max="99" /></label><p class="hw-hint">Add the casting ability modifier. Minimum 1 prepared spell. Granted spells will be reviewed separately.</p></div></div><div class="hw-subsection"><div class="hw-between"><h3>Class spell list</h3><span class="hw-pill">{{draft.magic.spellList.length}} selected</span></div><label>Find a spell<input v-model="spellQuery" type="search" placeholder="Search your spell library…" /></label><div class="hw-spell-picker" role="region" aria-label="Class spell list" tabindex="0"><label v-for="spell in spellResults" :key="spell.index" class="hw-spell-option"><input type="checkbox" :checked="draft.magic.spellList.includes(spellKey(spell))" @change="toggle(draft.magic.spellList,spellKey(spell))" /><span>{{contentLabel(spell)}}<small>{{spell.sourcePack||'SRD 2014'}}{{spell.level===undefined?'':spell.level===0?' · Cantrip':` · Spell level ${spell.level}`}}</small></span></label><p v-if="!spellResults.length" class="hw-hint">No matching spells.</p></div><p class="hw-hint">Showing up to 60 matches. Search to narrow the list. Each spell version is selected separately.</p><details v-if="unmatchedSpells.length" class="hw-callout"><summary>{{unmatchedSpells.length}} original spell references need a match</summary><p>These original references can be kept when saving other rule changes. Use Replace definition below to swap a reference in one step. The spell search above narrows these choices.</p><div v-for="key in unmatchedSpells" :key="key" class="hw-between"><span>{{spellReferenceLabel(key)}}</span><label>Replace definition<select :value="''" @change="draft.magic.spellList=[...new Set(draft.magic.spellList.map(id=>id===key?($event.target as HTMLSelectElement).value:id))]"><option value="" disabled>Choose the correct spell…</option><option v-for="spell in spellResults" :key="spell.index" :value="spell.index">{{contentLabel(spell)}} · {{spell.sourcePack||'SRD 2014'}}</option></select></label><button class="hw-text-button" type="button" :aria-label="`Remove unresolved reference ${key}`" @click="toggle(draft.magic.spellList,key)">Remove</button></div></details></div></template><p v-else class="hw-hint">The spellcasting section stays optional for martial classes and subclasses that inherit their parent’s magic.</p></div>
  <div v-else-if="step==='resources'" class="hw-section-body"><div class="hw-between"><div><h3>Make your class resources reusable.</h3><p class="hw-hint">Define the pool once. The preview shows its total at the chosen class level.</p></div><button type="button" class="hw-button" @click="draft.resources.push(newWorkshopResource())">+ Tracker</button></div><p v-if="!draft.resources.length" class="hw-empty-inline">Add points, dice, charges, or limited feature uses.</p><article v-for="(r,index) in draft.resources" :key="r.id" class="hw-rule-card"><div class="hw-between"><h4>{{r.name||`Resource ${index+1}`}}</h4><button type="button" class="hw-text-button" @click="draft.resources.splice(index,1)">Remove</button></div><div class="hw-form-grid"><label>Tracker name<input v-model="r.name" placeholder="Shadow points, Rift dice, feature uses…" /></label><label>Available from class level<input v-model.number="r.level" type="number" min="1" max="20" /></label><label>Calculate maximum from<select v-model="r.basis"><option value="fixed">Fixed amount</option><option value="level">Class level</option><option value="ability">Ability modifier</option><option value="proficiency">Proficiency bonus</option></select></label><label v-if="r.basis==='ability'">Ability<select v-model="r.ability"><option v-for="key in ABILITY_KEYS" :key="key" :value="key">{{key.toUpperCase()}}</option></select></label><label v-if="r.basis!=='fixed'">Multiply by<input v-model.number="r.multiplier" type="number" min="0" max="99" /></label><label>{{r.basis==='fixed'?'Total maximum':'Add base amount'}}<input v-model.number="r.base" type="number" min="0" max="999" /></label><label>Minimum pool<input v-model.number="r.minimum" type="number" min="0" max="999" /></label><label>Recovers on<select v-model="r.recovery"><option value="long">Long rest</option><option value="short">Short rest</option><option value="manual">Manual recovery</option></select></label><label>Unlimited from class level<input :value="r.unlimitedAt" type="number" min="1" max="20" placeholder="Never" @input="r.unlimitedAt=($event.target as HTMLInputElement).value===''?null:Number(($event.target as HTMLInputElement).value)" /></label></div><label>Use & recovery notes<textarea v-model="r.notes" rows="2" placeholder="Special uses, recovery rolls, or dice-size changes…" /></label></article></div>
  <div v-else-if="step==='features'" class="hw-section-body"><div class="hw-between"><p class="hw-hint">Give each feature a gained level. Choices also list the options offered to the player.</p><div class="hw-actions"><button type="button" class="hw-button" @click="draft.features.push(newWorkshopFeature())">+ Feature</button><button type="button" class="hw-button" @click="draft.features.push(newWorkshopFeature(true))">+ Choice</button></div></div><p v-if="!draft.features.length" class="hw-empty-inline">No features yet. Start with the defining ability of your class.</p><details v-for="(feature,index) in draft.features" :key="feature.id" class="hw-feature-editor" :open="!feature.name"><summary><span>{{feature.name||`New ${feature.choice?'choice':'feature'}`}}</span><small>Level {{feature.level}}</small></summary><div class="hw-feature-fields"><div class="hw-form-grid"><label>Name<input v-model="feature.name" /></label><label>Gained at class level<input v-model.number="feature.level" type="number" min="1" max="20" /></label><label v-if="feature.choice">Options players choose<input v-model.number="feature.choose" type="number" min="1" :max="feature.options.length||99" /></label></div><label>Rules & description<textarea v-model="feature.description" rows="5" /></label><label v-if="feature.choice">Available options · one per line<textarea :value="feature.options.join('\n')" rows="4" @change="feature.options=words(($event.target as HTMLTextAreaElement).value)" /></label><button type="button" class="hw-text-button" @click="draft.features.splice(index,1)">Remove {{feature.choice?'choice':'feature'}}</button></div></details></div>
  <div v-else class="hw-section-body"><div class="hw-review-status"><h3>{{problems.length?'A few details to complete':'Your draft is ready for review.'}}</h3><p class="hw-hint">{{draft.name||'Unnamed creation'}} · {{draft.kind}} · {{draft.source}}</p></div><ul v-if="problems.length" class="hw-alert"><li v-for="problem in problems" :key="problem">{{problem}}</li></ul><div class="hw-review-grid"><button v-for="section in WORKSHOP_STEPS.filter(s=>s.key!=='review')" :key="section.key" type="button" @click="emit('step',section.key)"><span>{{section.name}}</span><strong>{{section.key==='resources'?`${draft.resources.length} trackers`:section.key==='features'?`${draft.features.length} features / choices`:section.key==='magic'?draft.magic.enabled?`${draft.magic.ability.toUpperCase()} · ${draft.magic.progression}`:'No spellcasting':section.key==='progression'?draft.kind==='subclass'?'Inherit from class':`${draft.asiLevels.length} advancement levels`:section.key==='foundation'?draft.kind==='subclass'?'Inherit from class':`d${draft.hitDie} · ${draft.skillCount} skill choices`:draft.name||'Name needed'}}</strong><small>Review →</small></button></div><aside class="hw-callout"><strong>Ready to use these rules?</strong><p>Save into the original imported file, another pack, or a new pack. Linked characters update automatically while HP, spent uses, equipment, and selected choices are preserved. Conflicts appear on their character sheets.</p><p>Orcbrew exports standard DMV class fields. Advanced trackers and custom choices keep their full behavior on this site; the complete backup includes your library, characters, and drafts.</p></aside><button type="button" class="hw-button hw-button-primary" @click="emit('save')">Save draft on this device</button><button type="button" class="hw-button hw-button-primary" :disabled="!!problems.length" @click="emit('publish')">Save to pack & apply rules</button></div>
  <footer class="hw-editor-footer"><button type="button" class="hw-button" :disabled="stepIndex===0" @click="emit('step',WORKSHOP_STEPS[stepIndex-1]!.key)">← Back</button><span>{{stepIndex+1}} / {{WORKSHOP_STEPS.length}}</span><button v-if="stepIndex<WORKSHOP_STEPS.length-1" type="button" class="hw-button hw-button-primary" @click="emit('step',WORKSHOP_STEPS[stepIndex+1]!.key)">Next: {{WORKSHOP_STEPS[stepIndex+1]!.name}} →</button><button v-else type="button" class="hw-button" @click="emit('step','identity')">Back to identity</button></footer>
</section></template>
